export type Service = 'Web design' | 'Local SEO' | 'Branding' | 'E-commerce' | 'Google Ads' | 'Hosting & care';

export interface PortfolioMedia {
  hero: string;
  heroSm: string;
  full: { src: string; w: number; h: number } | null;
  mobile: string | null;
  /** Colour of the phone page's top edge; tints the frame's status bar. */
  mobileTop?: string;
  inner: { src: string; full: { src: string; w: number; h: number }; path: string; title: string }[];
  /** Full-length phone capture (390px viewport), only for sites shown on /web-design. */
  mobileFull?: { src: string; w: number; h: number } | null;
}

export interface Project {
  slug: string;
  name: string;
  url: string;
  industry: string;
  city?: string;
  services: Service[];
  stack?: string;
  summary: string;
  /** Shown in the homepage slides and the showreel, in this order. */
  featured?: number;
  /** Our build, but the client has since moved to another provider and the live domain shows
   *  someone else's site. Shown from our server copy, never linked. */
  archived?: boolean;
}

