const m = media as Record<string, PortfolioMedia>;
export const portfolio = projects
  .filter(p => m[p.slug])
  .map(p => ({ ...p, media: m[p.slug] }));
export type PortfolioItem = (typeof portfolio)[number];
export const featured = portfolio.filter(p => p.featured).sort((a, b) => (a.featured ?? 0) - (b.featured ?? 0));
export const host = (url: string) => url.replace(/^https?:\/\/(www\.)?/, '').replace(/\/$/, '');
